const HELPER="#!/usr/local/bin/prhm-node\n'use strict';\nconst fs=require('fs');\nconst path=require('path');\nconst crypto=require('crypto');\nconst cp=require('child_process');\n\nconst ACTION='mcp_candidate_schema_compare_v1';\nconst LIVE='/home/agent/ssh-mcp-server';\nconst STATE_DIR='/var/lib/prhm-agent-selfmaint-exec/mcp-candidate-schema-compare-v1';\nconst RESULT_FILE=path.join(STATE_DIR,'latest.json');\nconst LOCK_DIR=path.join(STATE_DIR,'lock');\nconst NODE='/usr/local/bin/prhm-node';\nconst TARGET_VERSION='0.16.0-policy-hardened';\nconst CANDIDATE_SOURCE_REF='maintenance/mcp-version-consistency-20260813';\nconst EXPECTED_PACKAGE_SHA='076139ca9c73e6bda5150b56bd3ff142991e3642fe27fa0be6fb4c3d56df4317';\nconst EXPECTED_LOCK_SHA='42093e620bf63fb3a65cdc69e2f14b03e291450776004b060435ce46a59de1f8';\nconst EXPECTED_PREINSTALL_PLUGIN_SHA='a1b7711fd0f981c3149c8417d60209b2913e06071617cfa93ee5d5db01e8f735';\nconst EXPECTED_POSTINSTALL_PLUGIN_SHA='92d043ddea8456b713a9646f314ece8e82eef89fd4e4169a9d95cdd4732ac7a3';\nconst EXPECTED_LIVE=Object.freeze({\n  server:'460aa5adebde7d4c696c05624969b548d8f1520b55fcdba5bea2e0c53b84602e',\n  registry:'96e5a80c62fdc7a74497ddb2fc50a29046fe6471462fd769d2c81189f86d619d',\n  selfmaint:'66f6154918e24339ab9afbfa6e7e7b7e36b1aa63475edc21ed07777b76267258',\n  leadops:'6d5ee216dc4309c77bc5793d0fca0c641eff0798bbc9742d24960425a0e08c66'\n});\n\nfunction shaBuffer(b){return crypto.createHash('sha256').update(b).digest('hex');}\nfunction shaFile(f){return shaBuffer(fs.readFileSync(f));}\nfunction fail(msg){throw new Error(msg);}\nfunction assertEq(actual,expected,label){if(actual!==expected)fail(`${label}:${actual}`);}\nfunction stable(v){if(Array.isArray(v))return v.map(stable);if(v&&typeof v==='object'){const o={};for(const k of Object.keys(v).sort())o[k]=stable(v[k]);return o;}return v;}\nfunction patchVersionText(text,isLock){const j=JSON.parse(text);j.version=TARGET_VERSION;if(isLock){if(!j.packages||!j.packages[''])fail('lock_root_missing');j.packages[''].version=TARGET_VERSION;}return JSON.stringify(j,null,2)+'\\n';}\nfunction portFree(port){const r=cp.spawnSync('/usr/bin/bash',['-lc',`ss -H -ltn '( sport = :${port} )'`],{encoding:'utf8',timeout:5000,env:{PATH:'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin'}});if(r.error)throw r.error;return String(r.stdout||'').trim()==='';}\nfunction verifySource(postInstall){\n  const files={server:path.join(LIVE,'server.js'),registry:path.join(LIVE,'src/core/registry.js'),plugin:path.join(LIVE,'src/plugins/hostActionsV2.js'),selfmaint:path.join(LIVE,'src/plugins/selfmaint.js'),leadops:path.join(LIVE,'src/plugins/leadops.js'),package:path.join(LIVE,'package.json'),lock:path.join(LIVE,'package-lock.json')};\n  for(const f of Object.values(files))if(!fs.existsSync(f))fail('missing:'+f);\n  assertEq(shaFile(files.server),EXPECTED_LIVE.server,'server_sha_mismatch');\n  assertEq(shaFile(files.registry),EXPECTED_LIVE.registry,'registry_sha_mismatch');\n  assertEq(shaFile(files.selfmaint),EXPECTED_LIVE.selfmaint,'selfmaint_sha_mismatch');\n  assertEq(shaFile(files.leadops),EXPECTED_LIVE.leadops,'leadops_sha_mismatch');\n  assertEq(shaFile(files.plugin),postInstall?EXPECTED_POSTINSTALL_PLUGIN_SHA:EXPECTED_PREINSTALL_PLUGIN_SHA,'plugin_sha_mismatch');\n  const pkg=JSON.parse(fs.readFileSync(files.package,'utf8'));\n  const lock=JSON.parse(fs.readFileSync(files.lock,'utf8'));\n  if(String(pkg.version)!=='0.15.0')fail('unexpected_live_package_version:'+pkg.version);\n  if(String(lock.version)!=='0.14.0'||String(lock.packages?.['']?.version)!=='0.14.0')fail('unexpected_live_lock_version');\n  const pkgCandidate=patchVersionText(fs.readFileSync(files.package,'utf8'),false);\n  const lockCandidate=patchVersionText(fs.readFileSync(files.lock,'utf8'),true);\n  assertEq(shaBuffer(Buffer.from(pkgCandidate)),EXPECTED_PACKAGE_SHA,'candidate_package_sha_mismatch');\n  assertEq(shaBuffer(Buffer.from(lockCandidate)),EXPECTED_LOCK_SHA,'candidate_lock_sha_mismatch');\n  if(!fs.existsSync(path.join(LIVE,'node_modules')))fail('live_node_modules_missing');\n  if(!portFree(8124))fail('candidate_port_8124_busy');\n  if(!portFree(8125))fail('baseline_port_8125_busy');\n  return {post_install:postInstall,source_ref:CANDIDATE_SOURCE_REF,target_version:TARGET_VERSION,plugin_sha256:shaFile(files.plugin),candidate_package_sha256:EXPECTED_PACKAGE_SHA,candidate_lock_sha256:EXPECTED_LOCK_SHA,ports:[8124,8125]};\n}\nfunction sleep(ms){return new Promise(r=>setTimeout(r,ms));}\nfunction spawnMcp(dir,port,token,label){\n  const env={PATH:'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin',NODE_ENV:'production',PORT:String(port),MCP_BEARER_TOKEN:token,ACTION_API_KEY:'candidate-no-network',SSH_AGENT_BASE_URL:'http://127.0.0.1:9',MCP_REQUEST_TIMEOUT_MS:'10000',MCP_MAX_CONCURRENT_REQUESTS:'2',MCP_DRAIN_GRACE_MS:'5000'};\n  const child=cp.spawn(NODE,[path.join(dir,'server.js')],{cwd:dir,env,stdio:['ignore','pipe','pipe']});\n  let stderr='',stdout='';\n  child.stdout.on('data',d=>{stdout=(stdout+d.toString()).slice(-8000);});\n  child.stderr.on('data',d=>{stderr=(stderr+d.toString()).slice(-8000);});\n  child._label=label;child._stderr=()=>stderr;child._stdout=()=>stdout;\n  return child;\n}\nasync function waitHealth(port,child){for(let i=0;i<80;i++){if(child.exitCode!==null)fail(child._label+'_exited:'+child.exitCode+':'+child._stderr().slice(-2000));try{const r=await fetch(`http://127.0.0.1:${port}/health`,{signal:AbortSignal.timeout(1000)});if(r.ok){const j=await r.json();if(j.ok===true&&j.version===TARGET_VERSION)return j;}}catch{}await sleep(100);}fail(child._label+'_health_timeout:'+child._stderr().slice(-2000));}\nasync function toolsList(port,token){const r=await fetch(`http://127.0.0.1:${port}/mcp`,{method:'POST',headers:{'content-type':'application/json','accept':'application/json, text/event-stream','authorization':'Bearer '+token},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/list',params:{}}),signal:AbortSignal.timeout(10000)});if(!r.ok)fail('tools_list_http_'+port+':'+r.status);const j=await r.json();if(!Array.isArray(j.result?.tools))fail('tools_list_invalid_'+port);return j.result.tools;}\nfunction schemaInfo(tools){const slim=tools.map(t=>({name:t.name,inputSchema:t.inputSchema||{}})).sort((a,b)=>a.name.localeCompare(b.name));const request=slim.find(t=>t.name==='host_action_v2_request');const values=request?.inputSchema?.properties?.action?.enum;if(!Array.isArray(values)||!values.includes(ACTION))fail('new_action_missing_from_schema');if(!slim.some(t=>t.name==='host_action_v2_apply'))fail('host_action_v2_apply_missing');return {count:slim.length,sha256:shaBuffer(Buffer.from(JSON.stringify(stable(slim))))};}\nfunction terminate(child){if(!child||!child.pid)return;try{process.kill(child.pid,'SIGTERM')}catch{}}\nfunction persist(result){fs.mkdirSync(STATE_DIR,{recursive:true,mode:0o700});const tmp=RESULT_FILE+'.'+process.pid+'.tmp';fs.writeFileSync(tmp,JSON.stringify(result)+'\\n',{mode:0o600});fs.renameSync(tmp,RESULT_FILE);}\nfunction copySource(src,dst){fs.mkdirSync(dst,{recursive:true,mode:0o700});const r=cp.spawnSync('rsync',['-a','--exclude=node_modules/','--exclude=.env',src+'/',dst+'/'],{encoding:'utf8',timeout:30000,env:{PATH:'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin'}});if(r.error)throw r.error;if(r.status!==0)fail('rsync_failed:'+String(r.stderr||'').slice(-1000));fs.symlinkSync(path.join(src,'node_modules'),path.join(dst,'node_modules'),'dir');}\nasync function runCompare(){\n  const pf=verifySource(true);\n  fs.mkdirSync(STATE_DIR,{recursive:true,mode:0o700});try{fs.mkdirSync(LOCK_DIR,{mode:0o700});}catch(e){if(e.code==='EEXIST')fail('mcp_candidate_schema_compare_already_running');throw e;}\n  const tmp=fs.mkdtempSync('/tmp/prhm-mcp-schema-compare-');const baseline=path.join(tmp,'baseline');const candidate=path.join(tmp,'candidate');let a,b;\n  try{\n    copySource(LIVE,baseline);copySource(LIVE,candidate);\n    fs.writeFileSync(path.join(candidate,'package.json'),patchVersionText(fs.readFileSync(path.join(candidate,'package.json'),'utf8'),false));\n    fs.writeFileSync(path.join(candidate,'package-lock.json'),patchVersionText(fs.readFileSync(path.join(candidate,'package-lock.json'),'utf8'),true));\n    assertEq(shaFile(path.join(candidate,'package.json')),EXPECTED_PACKAGE_SHA,'runtime_candidate_package_sha_mismatch');\n    assertEq(shaFile(path.join(candidate,'package-lock.json')),EXPECTED_LOCK_SHA,'runtime_candidate_lock_sha_mismatch');\n    const token=crypto.randomBytes(32).toString('hex');\n    a=spawnMcp(baseline,8125,token,'baseline');b=spawnMcp(candidate,8124,token,'candidate');\n    const [ha,hb]=await Promise.all([waitHealth(8125,a),waitHealth(8124,b)]);\n    const [ta,tb]=await Promise.all([toolsList(8125,token),toolsList(8124,token)]);\n    const sa=schemaInfo(ta),sb=schemaInfo(tb);\n    if(sa.count!==sb.count)fail('tool_count_mismatch:'+sa.count+':'+sb.count);\n    if(sa.sha256!==sb.sha256)fail('schema_fingerprint_mismatch:'+sa.sha256+':'+sb.sha256);\n    const result={schema_version:'prhm.host-action-result.v1',ok:true,action:ACTION,finished_at:new Date().toISOString(),candidate_source_ref:CANDIDATE_SOURCE_REF,target_version:TARGET_VERSION,baseline_health_version:ha.version,candidate_health_version:hb.version,baseline_tool_count:sa.count,candidate_tool_count:sb.count,baseline_schema_sha256:sa.sha256,candidate_schema_sha256:sb.sha256,schema_match:true,new_action_visible:true,candidate_package_sha256:EXPECTED_PACKAGE_SHA,candidate_lock_sha256:EXPECTED_LOCK_SHA,production_port_8123_restarted:false,production_source_mutated:false,production_secret_read:false,ephemeral_token_only:true,ports_cleaned:[8124,8125],preflight:pf};\n    persist(result);console.log(JSON.stringify(result));\n  }finally{terminate(a);terminate(b);await sleep(300);try{if(a?.pid)process.kill(a.pid,'SIGKILL')}catch{}try{if(b?.pid)process.kill(b.pid,'SIGKILL')}catch{}try{fs.rmSync(tmp,{recursive:true,force:true})}catch{}try{fs.rmdirSync(LOCK_DIR)}catch{}}\n}\nasync function main(){const args=process.argv.slice(2);if(args.length>1)fail('unexpected_arguments');if(args[0]==='--preflight-only'){console.log(JSON.stringify({schema_version:'prhm.host-action-preflight.v1',ok:true,action:ACTION,mode:'preinstall',...verifySource(false),production_mutation:false}));return;}if(args[0]==='--preflight-postinstall'){console.log(JSON.stringify({schema_version:'prhm.host-action-preflight.v1',ok:true,action:ACTION,mode:'postinstall',...verifySource(true),production_mutation:false}));return;}if(args.length!==0)fail('unexpected_argument:'+args[0]);await runCompare();}\nmain().catch(e=>{console.error(String(e&&e.stack||e));process.exit(1);});\n";
function shaText(s){return crypto.createHash('sha256').update(Buffer.from(s,'utf8')).digest('hex');}
function read(f){return fs.readFileSync(f,'utf8');}
function assertSha(label,file,expected){const actual=shaText(read(file));if(actual!==expected)throw Error(`sha_mismatch:${label}:${actual}`);}
function replaceOnce(text,anchor,replacement,label){const i=text.indexOf(anchor);if(i<0)throw Error(`anchor_missing:${label}`);if(text.indexOf(anchor,i+anchor.length)>=0)throw Error(`anchor_not_unique:${label}`);return text.slice(0,i)+replacement+text.slice(i+anchor.length);}
function insertAfterUniqueLine(text,needle,line,label){const rows=text.split('\n');const idx=[];rows.forEach((r,i)=>{if(r.includes(needle))idx.push(i)});if(idx.length!==1)throw Error(`line_anchor_count:${label}:${idx.length}`);const i=idx[0];if(!rows[i].trim().endsWith('}'))throw Error(`line_anchor_shape:${label}`);rows[i]=rows[i]+',';rows.splice(i+1,0,line);return rows.join('\n');}
function writeAtomic(file,text,mode,uid,gid){const tmp=`${file}.host-actions-v4-${process.pid}-${Date.now()}.tmp`;fs.writeFileSync(tmp,text,{mode});fs.chmodSync(tmp,mode);fs.chownSync(tmp,uid,gid);fs.renameSync(tmp,file);}
function backupFile(file,dir){const dest=path.join(dir,file.replace(/^\//,'').replace(/\//g,'__'));fs.copyFileSync(file,dest,fs.constants.COPYFILE_EXCL);fs.chmodSync(dest,0o600);return dest;}
function restore(file,backup){const st=fs.statSync(file);const data=fs.readFileSync(backup);const tmp=`${file}.rollback-${process.pid}-${Date.now()}.tmp`;fs.writeFileSync(tmp,data,{mode:st.mode&0o777});fs.chownSync(tmp,st.uid,st.gid);fs.renameSync(tmp,file);}
function nodeCheck(file){cp.execFileSync('/usr/local/bin/prhm-node',['--check',file],{stdio:'pipe',timeout:15000});}
function systemctl(...args){return cp.execFileSync('systemctl',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:30000}).trim();}
function curlUnix(socket,url){return cp.execFileSync('curl',['-fsS','--max-time','5','--unix-socket',socket,url],{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:8000}).trim();}
function sleep(ms){Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,ms);}
function waitFor(fn,attempts=30,delay=500){let last;for(let i=0;i<attempts;i++){try{const x=fn();if(x)return x;}catch(e){last=e}sleep(delay);}throw last||Error('health_timeout');}

function patchPolicy(input){const p=JSON.parse(input);if(p.schema_version!=='prhm.approval-policy.v1')throw Error('unexpected_policy_schema');p.version=VERSION;p.operations=p.operations||{};p.typed_scopes=Array.isArray(p.typed_scopes)?p.typed_scopes:[];p.operations[OPERATION]={level:4};const matches=p.typed_scopes.filter(x=>x&&x.tool==='host_action_v2_apply'&&x.project==='control_plane'&&x.environment==='production'&&x.action===ACTION&&x.risk==='critical'&&x.operation===OPERATION);if(matches.length>1)throw Error('duplicate_scope:'+ACTION);if(matches.length===0)p.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});return JSON.stringify(p,null,2)+'\n';}
function patchBase(input){if(input.includes(ACTION))throw Error('base_action_already_present');return insertAfterUniqueLine(input,"leadops_language_gate_v1: { operation: 'host_action.leadops_language_gate_v1'",`  ${ACTION}: { operation: '${OPERATION}', rollback: '${ROLLBACK}' }`,'base_spec');}
