  const unit='prhm-mcp-candidate-schema-compare-v1-'+Date.now();
  const args=['--wait','--unit='+unit,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=ProtectSystem=strict','--property=ProtectHome=read-only','--property=ReadWritePaths=/var/lib/prhm-agent-selfmaint-exec','--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',MCP_CANDIDATE_SCHEMA_COMPARE_HELPER];
  cp.execFileSync('/usr/bin/systemd-run',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:240000});
  if(!fs.existsSync(MCP_CANDIDATE_SCHEMA_COMPARE_RESULT))throw new Error('mcp_candidate_schema_compare_result_missing');
  const result=readJson(MCP_CANDIDATE_SCHEMA_COMPARE_RESULT);
  if(result.ok!==true||result.action!=='mcp_candidate_schema_compare_v1'||result.schema_version!=='prhm.host-action-result.v1'||result.schema_match!==true)throw new Error('mcp_candidate_schema_compare_result_invalid');
  return result;
