function patchExec(input){if(input.includes("mcp_candidate_schema_compare_v1:{operation:"))throw Error('exec_action_already_present');let out=insertAfterUniqueLine(input,"leadops_language_gate_v1:{operation:'host_action.leadops_language_gate_v1'",`  ${ACTION}:{operation:'${OPERATION}',kind:'mcp_candidate_schema_compare_v1'}`,'exec_spec');out=replaceOnce(out,'function verifyProcessSandboxV2(){',EXEC_HELPERS+'function verifyProcessSandboxV2(){','exec_helper');const dispatch="async function applyHostActionV2(action){const spec=hostActionV2Spec(action);if(action==='leadops_language_gate_v1')return applyLeadOpsLanguageGateV1();";out=replaceOnce(out,dispatch,dispatch+"if(action==='mcp_candidate_schema_compare_v1')return applyMcpCandidateSchemaCompareV1();",'exec_dispatch');out=replaceOnce(out,"version: '1.3.0-host-actions-v2-leadops-language-gate'","version: '1.4.0-host-actions-v2-mcp-candidate-schema-compare'",'exec_health_version');return out;}
function patchPlugin(input){if(input.includes("'mcp_candidate_schema_compare_v1'"))throw Error('plugin_action_already_present');let out=replaceOnce(input,"const HostActionV2=z.enum(['agent_api_process_sandbox_v1','agent_api_filesystem_confinement_v1','agent_api_capability_minimize_v1','leadops_language_gate_v1']);","const HostActionV2=z.enum(['agent_api_process_sandbox_v1','agent_api_filesystem_confinement_v1','agent_api_capability_minimize_v1','leadops_language_gate_v1','mcp_candidate_schema_compare_v1']);",'plugin_enum');out=replaceOnce(out,'Create a Level-4 request for a fixed staged control-plane action. Includes Agent API hardening and the no-input LeadOps language gate. No arbitrary command, path, SQL, or service input.','Create a Level-4 request for a fixed staged control-plane action. Includes Agent API hardening, the no-input LeadOps language gate, and the no-input MCP candidate schema comparison. No arbitrary command, path, SQL, or service input.','plugin_description');return out;}
function validate(patched){const p=JSON.parse(patched.policy);if(Number(p.operations?.[OPERATION]?.level)!==4)throw Error('policy_level_not_4');const scopes=p.typed_scopes.filter(x=>x&&x.tool==='host_action_v2_apply'&&x.action===ACTION&&x.operation===OPERATION&&x.project==='control_plane'&&x.environment==='production'&&x.risk==='critical');if(scopes.length!==1)throw Error('policy_scope_count:'+scopes.length);for(const x of [patched.base,patched.exec,patched.plugin])if(!x.includes(ACTION))throw Error('action_missing_candidate');if(!patched.exec.includes('applyMcpCandidateSchemaCompareV1'))throw Error('executor_helper_missing');if(!patched.plugin.includes('No arbitrary command, path, SQL, or service input.'))throw Error('plugin_description_not_hardened');if(shaText(patched.plugin)!==EXPECTED_POSTINSTALL_PLUGIN_SHA)throw Error('projected_plugin_sha_mismatch:'+shaText(patched.plugin));return true;}
