function selftest(){const p=patchPolicy(JSON.stringify({schema_version:'prhm.approval-policy.v1',version:'x',operations:{},typed_scopes:[]}));const base=`const HOST_ACTION_V2_SPECS = Object.freeze({\n  leadops_language_gate_v1: { operation: 'host_action.leadops_language_gate_v1', rollback: 'x' }\n});`;const exec=`const HOST_ACTION_V2_SPECS = Object.freeze({\n  leadops_language_gate_v1:{operation:'host_action.leadops_language_gate_v1',kind:'leadops_language_gate_v1'}\n});\nfunction verifyProcessSandboxV2(){}\nasync function applyHostActionV2(action){const spec=hostActionV2Spec(action);if(action==='leadops_language_gate_v1')return applyLeadOpsLanguageGateV1();\nreturn json(res, 200, { ok: true, service: 'x', version: '1.3.0-host-actions-v2-leadops-language-gate' });`;const plugin=`const HostActionV2=z.enum(['agent_api_process_sandbox_v1','agent_api_filesystem_confinement_v1','agent_api_capability_minimize_v1','leadops_language_gate_v1']);\nCreate a Level-4 request for a fixed staged control-plane action. Includes Agent API hardening and the no-input LeadOps language gate. No arbitrary command, path, SQL, or service input.`;const patched={policy:p,base:patchBase(base),exec:patchExec(exec),plugin:patchPlugin(plugin)};if(!patched.base.includes(ACTION)||!patched.exec.includes(ACTION)||!patched.plugin.includes(ACTION))throw Error('selftest_action_missing');return {ok:true,action:ACTION,version:VERSION,helper_sha256:shaText(HELPER)};}
function main(){if(process.argv.includes('--selftest-only')){console.log(JSON.stringify(selftest()));return;}const preflightOnly=process.argv.includes('--preflight-only');if(process.argv.length>3)throw Error('unexpected_arguments');if(process.getuid&&process.getuid()!==0)throw Error('root_required');if(fs.existsSync(PATHS.marker))throw Error('mcp_candidate_schema_compare_bootstrap_marker_exists');for(const [label,file] of Object.entries({policy:PATHS.policy,base:PATHS.base,exec:PATHS.exec,plugin:PATHS.plugin}))assertSha(label,file,EXPECTED[label]);if(fs.existsSync(PATHS.helper))throw Error('mcp_candidate_schema_compare_helper_already_exists');const originals={policy:read(PATHS.policy),base:read(PATHS.base),exec:read(PATHS.exec),plugin:read(PATHS.plugin)};const patched={policy:patchPolicy(originals.policy),base:patchBase(originals.base),exec:patchExec(originals.exec),plugin:patchPlugin(originals.plugin)};validate(patched);const dir=`/tmp/prhm-host-actions-v4-preflight-${process.pid}`;fs.mkdirSync(dir,{recursive:true,mode:0o700});const files={base:path.join(dir,'base-server.js'),exec:path.join(dir,'exec-server.js'),plugin:path.join(dir,'hostActionsV2.js'),helper:path.join(dir,'mcp-candidate-schema-compare-v1.js')};fs.writeFileSync(files.base,patched.base,{mode:0o600});fs.writeFileSync(files.exec,patched.exec,{mode:0o600});fs.writeFileSync(files.plugin,patched.plugin,{mode:0o600});fs.writeFileSync(files.helper,HELPER,{mode:0o700});nodeCheck(files.base);nodeCheck(files.exec);nodeCheck(files.plugin);nodeCheck(files.helper);JSON.parse(patched.policy);const helperPreflight=JSON.parse(cp.execFileSync('/usr/local/bin/prhm-node',[files.helper,'--preflight-only'],{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:30000}).trim());const report={ok:true,preflight_only:preflightOnly,action:ACTION,operation:OPERATION,current_hashes:EXPECTED,candidate_hashes:{policy:shaText(patched.policy),base:shaText(patched.base),exec:shaText(patched.exec),plugin:shaText(patched.plugin),helper:shaText(HELPER)},policy_version:VERSION,projected_plugin_sha256:EXPECTED_POSTINSTALL_PLUGIN_SHA,helper_preflight:helperPreflight};if(preflightOnly){console.log(JSON.stringify(report));return;}const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14);const backupDir=`/var/backups/prhm-host-actions-v4-mcp-candidate-schema-compare-${stamp}`;fs.mkdirSync(backupDir,{recursive:true,mode:0o700});const backups=[];let helperCreated=false;try{for(const f of [PATHS.policy,PATHS.base,PATHS.exec,PATHS.plugin])backups.push([f,backupFile(f,backupDir)]);const stats=Object.fromEntries([PATHS.policy,PATHS.base,PATHS.exec,PATHS.plugin].map(f=>[f,fs.statSync(f)]));writeAtomic(PATHS.policy,patched.policy,stats[PATHS.policy].mode&0o777,stats[PATHS.policy].uid,stats[PATHS.policy].gid);writeAtomic(PATHS.base,patched.base,stats[PATHS.base].mode&0o777,stats[PATHS.base].uid,stats[PATHS.base].gid);writeAtomic(PATHS.exec,patched.exec,stats[PATHS.exec].mode&0o777,stats[PATHS.exec].uid,stats[PATHS.exec].gid);writeAtomic(PATHS.plugin,patched.plugin,stats[PATHS.plugin].mode&0o777,stats[PATHS.plugin].uid,stats[PATHS.plugin].gid);fs.mkdirSync(path.dirname(PATHS.helper),{recursive:true,mode:0o755});writeAtomic(PATHS.helper,HELPER,0o700,0,0);helperCreated=true;systemctl('restart','prhm-company-approval.service');systemctl('restart','prhm-agent-selfmaint.service');systemctl('restart','prhm-agent-selfmaint-exec.service');systemctl('restart','prhm-agent-mcp.service');const health=JSON.parse(waitFor(()=>curlUnix('/run/prhm-agent-selfmaint-exec/exec.sock','http://localhost/health')));if(!Array.isArray(health.host_actions_v2)||!health.host_actions_v2.includes(ACTION))throw Error('mcp_candidate_schema_compare_missing_from_health');const postinstallPreflight=JSON.parse(cp.execFileSync('/usr/local/bin/prhm-node',[PATHS.helper,'--preflight-postinstall'],{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:30000}).trim());fs.writeFileSync(PATHS.marker,JSON.stringify({...report,postinstall_preflight:postinstallPreflight,installed_at:new Date().toISOString(),backup_dir:backupDir})+'\n',{flag:'wx',mode:0o600});console.log(JSON.stringify({...report,postinstall_preflight:postinstallPreflight,installed:true,backup_dir:backupDir}));}catch(error){const errs=[];if(helperCreated)try{fs.unlinkSync(PATHS.helper)}catch(e){if(e.code!=='ENOENT')errs.push('helper:'+e.message)}for(const [f,b] of backups.reverse())try{restore(f,b)}catch(e){errs.push(f+':'+e.message)}for(const s of ['prhm-company-approval.service','prhm-agent-selfmaint.service','prhm-agent-selfmaint-exec.service','prhm-agent-mcp.service'])try{systemctl('restart',s)}catch(e){errs.push(s+':'+e.message)}if(errs.length)throw Error('mcp_candidate_schema_compare_bootstrap_failed_and_rollback_failed:'+error.message+':'+errs.join('|'));throw Error('mcp_candidate_schema_compare_bootstrap_failed_rolled_back:'+error.message);}}
